import java.util.ArrayList;
import java.util.List;

class Solution {
    public ListNode partition(ListNode head, int x) {
        List<ListNode> smaller = new ArrayList<>();
        List<ListNode> other = new ArrayList<>();
        for (ListNode current = head; current != null; current = current.next) {
            if (current.val < x) smaller.add(current);
            else other.add(current);
        }
        List<ListNode> ordered = new ArrayList<>(smaller);
        ordered.addAll(other);
        if (ordered.isEmpty()) return null;
        for (int index = 0; index + 1 < ordered.size(); index++) ordered.get(index).next = ordered.get(index + 1);
        ordered.get(ordered.size() - 1).next = null;
        return ordered.get(0);
    }
}

