class Solution {
    public ListNode partition(ListNode head, int x) {
        ListNode smallerDummy = new ListNode(0);
        ListNode otherDummy = new ListNode(0);
        ListNode smallerTail = smallerDummy;
        ListNode otherTail = otherDummy;
        while (head != null) {
            ListNode next = head.next;
            head.next = null;
            if (head.val < x) { smallerTail.next = head; smallerTail = head; }
            else { otherTail.next = head; otherTail = head; }
            head = next;
        }
        smallerTail.next = otherDummy.next;
        return smallerDummy.next;
    }
}
